import java.io.Reader;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

public final class Importer {
    private Importer() {}

    public record PeakReading(String patientId, Instant recordedAt, int peakBpm) {}

    public static List<PeakReading> read(Reader source) throws IOException {
        BufferedReader input = new BufferedReader(source);
        String header = input.readLine();
        if (!"patient_id,recorded_at,peak_bpm".equals(header)) {
            throw new IllegalArgumentException("Unexpected CSV header");
        }
        List<PeakReading> readings = new ArrayList<>();
        String line;
        int row = 1;
        while ((line = input.readLine()) != null) {
            row++;
            String[] fields = line.split(",", -1);
            if (fields.length != 3 || fields[0].isBlank()) {
                throw new IllegalArgumentException("Invalid CSV row " + row);
            }
            Instant recordedAt = Instant.parse(fields[1]);
            int peakBpm = Integer.parseInt(fields[2]);
            if (peakBpm <= 0) {
                throw new IllegalArgumentException("Invalid peak rate at row " + row);
            }
